<?php
namespace Tests\Feature;
use App\Models\User; use App\Models\Workspace; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage; use Tests\TestCase;
class AssetVersionTest extends TestCase { use RefreshDatabase;
 private function setupWorkspace(string $role="owner"): array { Storage::fake("asset_originals"); $u=User::factory()->create(); $w=Workspace::factory()->create(); $w->users()->attach($u,["role"=>$role]); return [$u,$w]; }
 private function asset($u,$w,$key="a"): int { return $this->actingAs($u)->withHeader("Idempotency-Key",$key)->postJson("/workspaces/$w->id/assets",["file"=>\Illuminate\Http\UploadedFile::fake()->image("a.png")])->json("data.id"); }
 public function test_member_can_list_only_workspace_assets(): void { [$u,$w]=$this->setupWorkspace("member"); $other=Workspace::factory()->create(); $other->users()->attach($u,["role"=>"owner"]); $this->asset($u,$other); $this->actingAs($u)->getJson("/workspaces/$w->id/assets")->assertOk()->assertJsonPath("data",[]); }
 public function test_owner_creates_draft_version_bound_to_original(): void { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w); $this->actingAs($u)->postJson("/workspaces/$w->id/assets/$id/versions",["label"=>"draft"])->assertCreated()->assertJsonPath("data.asset_id",$id)->assertJsonPath("data.status","draft"); $this->assertDatabaseHas("asset_versions",["asset_id"=>$id,"original_sha256"=>DB::table("assets")->find($id)->sha256]); }
 public function test_version_replay_is_rejected_and_original_fields_immutable(): void { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w); $r=$this->actingAs($u)->postJson("/workspaces/$w->id/assets/$id/versions",[])->assertCreated(); $this->postJson("/workspaces/$w->id/assets/$id/versions",[])->assertCreated()->assertJsonPath("data.id",$r->json("data.id")); $this->assertDatabaseMissing("assets",["id"=>$id,"sha256"=>"changed"]); }
 public function test_unauthorized_role_and_tenant_are_forbidden(): void { [$u,$w]=$this->setupWorkspace("member"); $this->actingAs($u)->getJson("/workspaces/$w->id/assets")->assertOk(); $other=Workspace::factory()->create(); $this->actingAs($u)->getJson("/workspaces/$other->id/assets")->assertForbidden(); }
 public function test_replay_returns_same_version_and_rejects_changed_metadata(): void { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w); $url="/workspaces/$w->id/assets/$id/versions"; $first=$this->actingAs($u)->postJson($url,["label"=>"first"])->assertCreated(); $this->postJson($url,["label"=>"first"])->assertCreated()->assertJsonPath("data.id",$first->json("data.id")); $this->postJson($url,["label"=>"different"])->assertConflict(); $this->assertDatabaseCount("asset_versions",1); }
 public function test_pending_assets_are_not_listed_or_versioned(): void { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w); DB::table("assets")->where("id",$id)->update(["status"=>"pending"]); $this->actingAs($u)->getJson("/workspaces/$w->id/assets")->assertOk()->assertJsonPath("data",[]); $this->postJson("/workspaces/$w->id/assets/$id/versions",[])->assertConflict(); $this->assertDatabaseCount("asset_versions",0); }
 public function test_missing_or_corrupt_original_cannot_create_or_replay_version(): void { foreach (["missing","corrupt"] as $mode) { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w,$mode); $asset=DB::table("assets")->find($id); if($mode==="missing") Storage::disk("asset_originals")->delete($asset->path); else Storage::disk("asset_originals")->put($asset->path,"corrupt"); $this->actingAs($u)->postJson("/workspaces/$w->id/assets/$id/versions",[])->assertConflict(); } $this->assertDatabaseCount("asset_versions",0); }
 public function test_version_metadata_and_checksum_cannot_be_mutated(): void { [$u,$w]=$this->setupWorkspace(); $id=$this->asset($u,$w); $original=DB::table("assets")->find($id); $response=$this->actingAs($u)->postJson("/workspaces/$w->id/assets/$id/versions",["label"=>"safe","original_sha256"=>str_repeat("f",64),"status"=>"published","asset_id"=>999])->assertCreated(); $version=\App\Models\AssetVersion::findOrFail($response->json("data.id")); $this->assertSame($original->sha256,$version->original_sha256); $this->assertSame("draft",$version->status); $version->label="changed"; try { $version->save(); } catch (\LogicException $e) {} $this->assertDatabaseHas("asset_versions",["id"=>$version->id,"label"=>"safe","original_sha256"=>$original->sha256,"status"=>"draft"]); $this->assertEquals($original,DB::table("assets")->find($id)); }
 public function test_cross_workspace_and_read_only_roles_cannot_create_versions(): void { [$owner,$w]=$this->setupWorkspace(); $id=$this->asset($owner,$w); $other=Workspace::factory()->create(); $other->users()->attach($owner,["role"=>"owner"]); $this->actingAs($owner)->postJson("/workspaces/$other->id/assets/$id/versions",[])->assertForbidden(); foreach (["member","viewer"] as $role) { $u=User::factory()->create(); $w->users()->attach($u,["role"=>$role]); $this->actingAs($u)->postJson("/workspaces/$w->id/assets/$id/versions",[])->assertForbidden(); } $this->assertDatabaseCount("asset_versions",0); }
}
